#include <vector.h>

class string_buf;
class stringx
{
protected:
  char *chars;
  string_buf *my_buf;
};

class path_graph_edge
{
public:
  virtual ~path_graph_edge();
};

class path_graph_node
{
public:
  virtual ~path_graph_node();
};

class path_graph
{
protected:
  stringx id;
  vector<path_graph_node*> nodes;
  vector<path_graph_edge*> edges;
public:
  void clear();
};

void path_graph::clear()
{
  vector<path_graph_edge *>::iterator i = edges.begin();
  while(i != edges.end())
  {
    if(*i != NULL)
    {
      path_graph_edge *edge = *i;
      i = edges.erase(i);

      delete edge;
    }
    else
      ++i;
  }

  vector<path_graph_node *>::iterator j = nodes.begin();
  while(j != nodes.end())
  {
    if(*j != NULL)
    {
      path_graph_node *node = *j;
      j = nodes.erase(j);

      delete node;
    }
    else
      ++j;
  }
}
